import { people } from './company-model.mjs';
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo = (file,label) => `<span class="work-brand"><img src="assets/${file}" alt="">${label}</span>`;
const chat = (speaker,text,kind='') => `<div class="work-message ${kind}"><small>${speaker}</small><p>${text}</p></div>`;
const table = (headers,rows,highlight=[]) => `<table class="work-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${highlight.includes(i)?'work-changed':''}">${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
