export function employeeStrip(selected) {
 return `<nav class="employee-strip" aria-label="Choose an employee">${people.map(p=>`<button data-workspace="${p.id}" aria-pressed="${p.id===selected}"><b>${p.name}</b><span>${p.department}</span></button>`).join('')}</nav>`;
}
function financeWork(step) {
 if(step>=2)return `<div class="work-appbar excel-bar">${logo('ms-excel.svg','Excel · Priya’s monthly report')}<small>Saved Power Query method</small></div><div class="work-body finance-payoff"><div class="transformation-receipt"><span>Vendor / Supplier / Payee</span><b>→</b><span>Vendor + Invoice + Amount</span></div><p class="payoff-source">Built and debugged with Claude. Excel now runs the reviewed transformation.</p>${table(['Vendor','Invoice','Amount','Priya’s review'],[['Acme Ltd','N101','$1,200','Keep'],['Acme Ltd','N101','$1,200','Confirmed duplicate'],['North Office','W203','$850','Keep']],[1])}<div class="exception-decision"><b>Priya checks the exception.</b><span>She confirms the repeated invoice. Two rows enter the report; original files stay intact.</span></div><div class="repeatable-receipt"><b>Next month: Refresh → review exceptions → report</b><span>The work pays off again without repeating the chat.</span></div></div>`;

 return `<div class="work-appbar excel-bar">${logo('ms-excel.svg','Excel · Monthly branch report')}<small>Excel runs the saved transformation</small></div><div class="work-body finance-work"><div class="incoming-files"><section><b>North.csv</b><span>Vendor / Amount</span><code>Acme Ltd / 1,200</code></section><section><b>East.xlsx</b><span>Supplier / Total</span><code>ACME LTD. / 1,200</code></section><section><b>West.csv</b><span>Payee / Cost</span><code>North Office / 850</code></section></div><div class="work-chat-excerpt ${step?'work-chat-compact':''}">${logo('claude.svg','Earlier · Claude helped build the transformation')}<p><b>Priya:</b> “Normalize these headers and vendor spellings. Flag duplicate invoices. Do not delete rows.”</p><p><b>Claude:</b> “Standardize the fields, then route repeated invoice IDs to a review table.”</p></div>${step?table(['Vendor','Invoice','Amount','Review'],[['Acme Ltd','N101','$1,200','Ready'],['Acme Ltd','N101','$1,200',step>1?'Excluded duplicate':'Possible duplicate'],['North Office','W203','$850','Ready']],[1]):'<div class="work-empty">Saved transformation ready.<br><strong>One refresh. Three branch formats.</strong></div>'}${step?`<p class="work-result">${step>1?'Priya confirms the duplicate. Two rows are ready; the original files are preserved.':'One possible duplicate needs Priya’s judgment. Nothing was silently discarded.'}</p>`:''}</div>`;
}
function workSurface(id,step) {
 if(id==='priya')return financeWork(step);
 if(id==='ben')return `<div class="work-appbar excel-bar">${logo('ms-excel.svg','Excel · Four Friday pipeline snapshots')}${logo('copilot.webp','Copilot')}</div><div class="work-body">${table(['Opportunity','Oct 16','Oct 23','Oct 30','Nov 6'],[['Atlas renewal','Oct 30','Nov 6','Nov 20','Nov 20'],['Beacon expansion','Oct 23','Nov 6','Nov 27','Nov 27'],['Delta rollout','Oct 30','Nov 13','Nov 27','Nov 27'],['Harbor services','Nov 20','Nov 20','Nov 20','Nov 20']],step?[0,1,2]:[])}${chat('BEN’S SAVED PROMPT','Flag deals with two date changes and no new buyer activity.','prompt')}${step?chat('COPILOT · CHECK AGAINST THE HIGHLIGHTED ROWS','Three deals moved twice. <mark>Check buyer evidence with these reps.</mark> Ben verifies the source rows before coaching.'):''}</div>`;
 if(id==='nina')return `<div class="work-appbar teams-bar">${logo('ms-teams.svg','Teams · Ask Ops')}<small>6 people use this each morning</small></div><div class="work-body">${chat('NINA','What kept coming back? Group the issues and show the original cases.','prompt')}${step?`<div class="ops-groups"><span><b>8</b> possible handoffs</span><span><b>6</b> billing questions</span><span><b>4</b> access requests</span></div><div class="source-case-preview"><small>ORIGINAL RECORD · CASE-201</small><p>Implementation marked its step complete. The receiving service-owner field was empty. The customer asked who would handle the next step.</p><button class="text-button" data-detail="source:CASE-201">Inspect source ↗</button></div><p class="work-result">Nina checks the source before accepting the grouping. The bot assists her judgment.</p>`:'<div class="work-empty">A useful department bot is ready.<br><strong>Other teams still inspect the cases one by one.</strong></div>'}</div>`;
 if(id==='marcus')return `<div class="phone-scene"><div class="practice-phone"><div class="phone-speaker"></div><div class="work-appbar">${logo('grok.svg','Grok · Practice')}<small>Captioned role-play</small></div><div class="phone-captions">${step<2?chat('MARCUS','Play a frustrated customer. Interrupt me if my answer is vague.','prompt'):''}${step===1?chat('CUSTOMER · AI ROLE-PLAY','“I have explained this to three teams. Who is actually helping me?”'):''}${step>=2?`${chat('MARCUS','“Someone will get back to you.”','prompt')}${chat('CUSTOMER · AI ROLE-PLAY','“Who? And when?”')}`:''}${step>=3?chat('MARCUS · SECOND TRY','“I am your contact. I will confirm the owner and call you by 3 PM.”','improved'):''}</div></div><p class="phone-context">Generic scenario.<br>No customer names or records.<br><b>Private chat stays private.</b></p></div>`;
 if(id==='ava')return `<div class="work-appbar">${logo('ms-outlook.svg','Ava · Customer reply')}${logo('copilot.webp','Copilot')}</div><div class="work-body">${step>=2?`<div class="ava-payoff"><section><small>BEFORE SHE COULD DRAFT</small><div class="compact-ticket-history">${['Implementation notes elsewhere','Reassigned to Service','Receiving owner unclear','Customer repeats details','Ava asks Ops for context','Ava checks promised callback'].map((t,i)=>`<p><b>${201+i}</b><span>${t}</span></p>`).join('')}</div></section><section><small>THE AI-ASSISTED REPLY</small>${chat('COPILOT · AVA REVIEWS','“You shouldn’t have to repeat the details. I’m confirming the owner with Operations and will update you today.”','improved')}</section></div><p class="work-result warning">The wording is better. Finding the facts still required six records.</p>`:`${chat('AVA’S ORIGINAL DRAFT','I understand you have already explained this. I have asked Operations to confirm the next owner and will update you today.','draft')}${chat('AVA → COPILOT','Make this warmer and shorter without adding a promise.','prompt')}`}</div>`;
 if(id==='elena')return `<div class="work-appbar">${logo('ms-excel.svg','Excel · Thursday commitments')}<small>Update due 4 PM</small></div><div class="work-body">${table(['Commitment','Owner','Due'],[['Confirm rollout scope','Unassigned','Nov 12'],['Validate branch totals','Priya','Nov 9'],['Send account update','Marcus','Nov 10']])}${step?`<div class="abandoned-chat ${step===2?'attempt-closed':''}">${logo('copilot.webp','Copilot · Her first attempt')}${chat('ELENA','Help with my projects.','prompt')}${chat('COPILOT','Set clear goals, prioritize your tasks, and communicate regularly with stakeholders.')}</div>`:'<div class="work-empty">Meeting notes and email updates still need comparing.</div>'}${step===2?'<p class="work-result warning">3:42 PM. Elena returns to copying dates and owners by hand. She wants help with this task.</p>':''}</div>`;
 if(id==='daniel')return `<div class="work-appbar teams-bar">${logo('ms-teams.svg','Teams · Ask Parkside')}<small>Approved SharePoint sources</small></div><div class="work-body">${chat('EMPLOYEE','How do I escalate a client issue?','prompt')}${step?`<div class="procedure-answer"><small>ASK PARKSIDE · APPROVED PROCEDURE</small><ol><li>Name one accountable owner.</li><li>Record the next customer update.</li><li>Link the receiving team to the original case.</li></ol><button class="text-button" data-detail="procedure">Customer Escalation Procedure · §3 ↗</button></div><div class="launch-feedback compact-feedback"><b>Daniel: “Try it and tell us what helps.”</b><span>Feedback: “Thanks!” · 👍</span><p>He can measure opens. He still needs examples of improved work.</p></div>`:'<div class="work-empty">A sourced company answer is ready.<br><strong>What happens after employees use it?</strong></div>'}</div>`;
 if(id==='dana')return `<div class="work-appbar">${logo(step?'claude.svg':'ms-powerpoint.svg',step?'Claude · Board preparation':'PowerPoint · AI rollout update')}</div><div class="work-body">${step?`${chat('DANA','Act like a skeptical board member. Which claim would you challenge? What evidence should I bring?','prompt')}${chat('CLAUDE','You show access and usage. <mark>What changed in the time it takes to finish work across departments?</mark> Bring a specific before-and-after workflow, not just an adoption total.')}${chat('DANA','That’s a better question. I will ask how the weekly brief is actually prepared.','improved')}`:'<div class="rollout-metrics"><section><strong>150</strong><span>Copilot licenses assigned</span></section><section><strong>Live</strong><span>Company assistant</span></section><section><strong>Working</strong><span>Sales forecast review</span></section></div><blockquote class="work-bigquote">“I’ve seen what Sales can do. And Claude helps me prepare for every board meeting.”</blockquote>'}</div>`;
 return `<div class="work-appbar teams-bar">${logo('ms-teams.svg','Leah · Friday briefing')}${logo('copilot.webp','Copilot')}</div><div class="work-body">${step>=2?`<div class="leah-payoff"><section><small>LEAH’S MANUAL RECONCILIATION</small><div class="reconciliation-rows"><p><b>Sales</b><span>Atlas moved. Which forecast version?</span></p><p><b>Operations</b><span>“Northwind setup came back.”</span></p><p><b>Service</b><span>“NW Services. Update Tuesday.”</span></p></div><p class="reconciliation-question">Same customer? Which Tuesday? Who owns the next step?</p></section><section><small>DANA RECEIVES THE POLISHED BRIEF</small>${chat('COPILOT · BASED ON THE PROVIDED BRIEF','“Sales revised its forecast. Operations handled 18 escalations. Service responded to every inquiry.”')}</section></div><p class="work-result warning">Copilot polished the wording. Leah still had to reconcile the facts, and the potential cross-team pattern is absent.</p>`:'<div class="work-empty"><strong>Weekly briefing · Unfinished</strong><br>Updates received. Owners, dates and assumptions still need checking.</div>'}</div>`;
}
function peerWork(id,story) {
 const preview=id==='priya'?`${table(['Maya’s branch input','Manual step'],[['Supplier','Rename to Vendor'],['ACME LTD.','Correct spelling'],['Invoice N101','Check against other files']])}<p class="peer-work-status">Priya has already solved this pattern. Maya does not know the method exists.</p>`:id==='ben'?table(['Other manager’s export','Checked?'],[['This week: $2.4m','Yes'],['Last week: $2.5m','Yes'],['Dates moved twice','Not compared']]):id==='nina'?`<div class="peer-manual-cases"><p>CASE-201 → read and copy</p><p>CASE-204 → read and compare</p><p>CASE-207 → rebuild the pattern</p></div><p class="peer-work-status">Service is doing its own review of the same evidence.</p>`:'<p class="peer-practice-request">“Could I practice before my next call?”</p>';
 return `<div class="peer-reveal"><small>WHO ELSE COULD USE THIS?</small><h3>${story.peerTitle}</h3><div class="peer-task">${logo(id==='marcus'?'grok.svg':id==='nina'?'zendesk.svg':'ms-excel.svg',story.peerTool)}${preview}</div></div>`;
}
export function renderWorkspace(state,personId=state.workspace||state.person) {
 const person=people.find(p=>p.id===personId)||people[3];const id=person.id;const story=workspaceStories[id];const step=state.workSteps?.[id]||0;
 const done=step>=story.max;const peer=done&&story.peer;
 return `<section class="employee-workspace"><div class="workspace-top"><span><b>${person.name}</b> · ${person.department}</span><button data-close-workspace>← Company view</button></div><div class="workspace-columns"><section class="work-surface ${id}">${workSurface(id,step)}</section><aside class="work-story"><blockquote>${story.quote}</blockquote>${peer?peerWork(id,story):`<div><small>WHAT WORKS</small><p>${story.situation}</p></div><div class="work-consequence"><small>WHAT THE COMPANY DOESN’T SEE</small><p>${story.consequence}</p></div>`}<div class="workspace-actions">${id==='marcus'?`<button class="primary" data-work-action="marcus">${step?'Replay captioned practice':'Play captioned practice'}</button>`:done?'<p class="workspace-complete">The result and remaining work are shown together.</p>':`<button class="primary" data-work-reveal="${id}">Show ${person.name}’s work</button>`}</div></aside></div>${employeeStrip(id)}</section>`;
}
export function workspaceHeading(state) {const id=state.workspace||state.person;return workspaceStories[id]?.title;}
